// Monochrome marks, all rendering in currentColor.
// Brand paths inlined from simple-icons (CC0) and devicon (MIT) so neither
// package ships as a runtime dependency.

type MarkProps = { className?: string }

const mark = (d: string, viewBox = "0 0 24 24", evenOdd = false) =>
  function Mark({ className }: MarkProps) {
    return (
      <svg viewBox={viewBox} aria-hidden="true" className={className} fill="currentColor">
        <path
          d={d}
          fillRule={evenOdd ? 'evenodd' : undefined}
          clipRule={evenOdd ? 'evenodd' : undefined}
        />
      </svg>
    )
  }

