/*
  Drawn glyphs, not logos. SQL has no brand mark, and Delta Lake, Microsoft
  Fabric and OneLake have no mark that is free to redistribute, so these are
  purpose-drawn in the same geometric language as the rest of the page rather
  than being faked from memory.
*/
const glyph = (children: React.ReactNode) =>
  function Glyph({ className }: MarkProps) {
    return (
      <svg
        viewBox="0 0 24 24"
        aria-hidden="true"
        className={className}
        fill="none"
        stroke="currentColor"
        strokeWidth={1.6}
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        {children}
      </svg>
    )
  }

/* A delta with its strata: layers read inside the triangle, not under it,
   so it does not collapse into the eject symbol. */
